#!/usr/bin/env bash
# GSZ step121 — notification cleanup: reseller-bot owner alerts only for
# new/delivered/rejected/review, once each (atomic dedup via orders.owner_alerts);
# and the WhatsApp delivery message sends the fulfilment text verbatim (no
# double wrapper / no "reply here"). Safe + idempotent; restores on failure.
set -euo pipefail
GSZ=/opt/gsz; TS=$(date +%Y%m%d-%H%M%S); BK="$GSZ/.bak-step121-$TS"; TMP=$(mktemp -d)
F=routes/checkout.js
echo "==> step121: notification cleanup"
mkdir -p "$BK/$(dirname "$F")"; cp "$GSZ/$F" "$BK/$F"; echo "    backup: $BK"
restore(){ echo "!! FAILED — restoring"; cp "$BK/$F" "$GSZ/$F"; pm2 restart gsz >/dev/null 2>&1 || true; echo "!! restored."; }
trap 'restore' ERR
echo "" | base64 -d > "$TMP/p.js"
echo ""   | base64 -d > "$TMP/m.js"
echo "==> applying"; node "$TMP/p.js" "$GSZ"; node --check "$GSZ/$F"
echo "==> migrating db"; ( cd "$GSZ" && NODE_PATH="$GSZ/node_modules" node "$TMP/m.js" )
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz; sleep 2
CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/ || true); [ "$CODE" = "200" ] && echo "    homepage 200: OK" || { echo "    homepage $CODE"; false; }
trap - ERR; rm -rf "$TMP"
echo ""; echo "==> step121 OK ✅  Reseller bot now gets at most: New order, Delivered, plus Rejected/Needs-review — once each, no duplicates. Delivery WhatsApp message is clean (fulfilment text only)."
